import { relations } from 'drizzle-orm';
import {
	boolean,
	index,
	integer,
	jsonb,
	pgTable,
	text,
	timestamp,
	uniqueIndex,
	uuid
} from 'drizzle-orm/pg-core';
import type { Decision, Intent } from '../policy';
import type { MandateStatus, Narrowing } from '../mandate';

/**
 * Money is always integer cents plus a currency code, never a float and never a
 * bare number. The columns are written out rather than generated by a helper,
 * because a computed key stops TypeScript from seeing the column names.
 */

export const mandate = pgTable(
	'mandate',
	{
		id: text('id').primaryKey(),
		ownerId: text('owner_id').notNull(),
		agentId: text('agent_id').notNull(),
		purpose: text('purpose').notNull(),
		allowedCategories: jsonb('allowed_categories').$type<string[]>().notNull().default([]),
		ceilingCents: integer('ceiling_cents').notNull(),
		ceilingCurrency: text('ceiling_currency').notNull().default('USD'),
		perTransactionCapCents: integer('per_transaction_cap_cents').notNull(),
		perTransactionCapCurrency: text('per_transaction_cap_currency').notNull().default('USD'),
		autoApproveAmountCents: integer('auto_approve_amount_cents').notNull(),
		autoApproveAmountCurrency: text('auto_approve_amount_currency').notNull().default('USD'),
		/** PayPal `payee.merchant_id` values. Never display names. */
		allowedMerchants: jsonb('allowed_merchants').$type<string[]>().notNull().default([]),
		expiresAt: timestamp('expires_at', { withTimezone: true, mode: 'date' }).notNull(),
		status: text('status').$type<MandateStatus>().notNull().default('active'),
		revokedAt: timestamp('revoked_at', { withTimezone: true, mode: 'date' }),
		createdAt: timestamp('created_at', { withTimezone: true, mode: 'date' }).notNull().defaultNow()
	},
	(table) => [index('mandate_owner_idx').on(table.ownerId, table.status)]
);

export const spendRequest = pgTable(
	'spend_request',
	{
		id: uuid('id').primaryKey().defaultRandom(),
		mandateId: text('mandate_id')
			.notNull()
			.references(() => mandate.id, { onDelete: 'restrict' }),
		agentId: text('agent_id').notNull(),
		/**
		 * sha256 of mandate, agent, raw text, amount and merchant. All knowable
		 * before the model runs, so a retry cannot become a second payment.
		 */
		idempotencyKey: text('idempotency_key').notNull(),
		rawRequest: text('raw_request').notNull(),
		intent: jsonb('intent').$type<Intent>(),
		amountCents: integer('amount_cents').notNull(),
		amountCurrency: text('amount_currency').notNull().default('USD'),
		merchantId: text('merchant_id'),
		merchantEmail: text('merchant_email'),
		paypalOrderId: text('paypal_order_id'),
		paypalAuthorizationId: text('paypal_authorization_id'),
		status: text('status')
			.$type<'pending' | 'allowed' | 'denied' | 'expired' | 'captured' | 'failed' | 'refunded'>()
			.notNull()
			.default('pending'),
		verdict: text('verdict').$type<Decision['verdict']>(),
		decidingRule: text('deciding_rule').$type<Decision['rule'] | 'mandate_narrowed'>(),
		reason: text('reason'),
		decidedBy: text('decided_by').$type<'policy' | 'human' | null>(),
		failure: jsonb('failure').$type<{ issue: string; body: string } | null>(),
		createdAt: timestamp('created_at', { withTimezone: true, mode: 'date' }).notNull().defaultNow(),
		resolvedAt: timestamp('resolved_at', { withTimezone: true, mode: 'date' })
	},
	(table) => [
		uniqueIndex('spend_request_idempotency_idx').on(table.idempotencyKey),
		index('spend_request_mandate_idx').on(table.mandateId, table.createdAt)
	]
);

export const mandateEvent = pgTable(
	'mandate_event',
	{
		id: uuid('id').primaryKey().defaultRandom(),
		mandateId: text('mandate_id')
			.notNull()
			.references(() => mandate.id, { onDelete: 'restrict' }),
		kind: text('kind').$type<'created' | 'narrowed' | 'revoked'>().notNull(),
		change: jsonb('change').$type<Narrowing | null>(),
		by: text('by').$type<'human'>().notNull(),
		at: timestamp('at', { withTimezone: true, mode: 'date' }).notNull().defaultNow()
	},
	(table) => [index('mandate_event_mandate_idx').on(table.mandateId, table.at)]
);

export type LedgerEventKind =
	| 'requested'
	| 'allowed'
	| 'denied'
	| 'escalated'
	| 'approved'
	| 'authorized'
	| 'hold_released'
	| 'captured'
	| 'refunded'
	| 'disputed'
	| 'failed';

export const ledgerEvent = pgTable(
	'ledger_event',
	{
		id: uuid('id').primaryKey().defaultRandom(),
		/** Nullable because a mandate revocation is recorded with no request. */
		spendRequestId: uuid('spend_request_id').references(() => spendRequest.id, {
			onDelete: 'restrict'
		}),
		mandateId: text('mandate_id')
			.notNull()
			.references(() => mandate.id, { onDelete: 'restrict' }),
		kind: text('kind').$type<LedgerEventKind>().notNull(),
		amountCents: integer('amount_cents').notNull(),
		amountCurrency: text('amount_currency').notNull().default('USD'),
		merchantId: text('merchant_id'),
		paypalId: text('paypal_id'),
		/** PayPal's own webhook event id, so a duplicate delivery is one row. */
		externalId: text('external_id'),
		payload: jsonb('payload'),
		occurredAt: timestamp('occurred_at', { withTimezone: true, mode: 'date' }).notNull(),
		receivedAt: timestamp('received_at', { withTimezone: true, mode: 'date' })
			.notNull()
			.defaultNow()
	},
	(table) => [
		uniqueIndex('ledger_event_external_idx').on(table.externalId),
		index('ledger_event_mandate_idx').on(table.mandateId, table.occurredAt)
	]
);

export const receipt = pgTable('receipt', {
	id: uuid('id').primaryKey().defaultRandom(),
	spendRequestId: uuid('spend_request_id')
		.notNull()
		.references(() => spendRequest.id, { onDelete: 'cascade' }),
	/** Written once, so a change in wording is traceable to a model version. */
	text: text('text').notNull(),
	model: text('model').notNull(),
	createdAt: timestamp('created_at', { withTimezone: true, mode: 'date' }).notNull().defaultNow()
});

export const mandateRelations = relations(mandate, ({ many }) => ({
	requests: many(spendRequest),
	events: many(mandateEvent)
}));

export const spendRequestRelations = relations(spendRequest, ({ one, many }) => ({
	mandate: one(mandate, { fields: [spendRequest.mandateId], references: [mandate.id] }),
	ledger: many(ledgerEvent),
	receipt: one(receipt, { fields: [spendRequest.id], references: [receipt.spendRequestId] })
}));

export const ledgerEventRelations = relations(ledgerEvent, ({ one }) => ({
	request: one(spendRequest, {
		fields: [ledgerEvent.spendRequestId],
		references: [spendRequest.id]
	}),
	mandate: one(mandate, { fields: [ledgerEvent.mandateId], references: [mandate.id] })
}));
